'use strict';
const $=id=>document.getElementById(id);
const icons={plane:'<path d="m22 3-8 18-3-8-8-3Z"/><path d="m11 13 5-5"/>',car:'<path d="m5 8 2-5h10l2 5M3 9h18v9H3zM5 18v3m14-3v3M6 13h2m8 0h2"/>',bed:'<path d="M3 20V7m18 13v-9H3m0 6h18M7 7V4h10v7M3 7h7"/>',coffee:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4ZM17 9h2a3 3 0 0 1 0 6h-2M7 2v3m5-3v3M2 22h18"/>',waves:'<path d="M2 7c3-5 7 5 10 0s7 5 10 0M2 13c3-5 7 5 10 0s7 5 10 0M2 19c3-5 7 5 10 0s7 5 10 0"/>',bag:'<path d="M4 7h16l1 15H3ZM8 8V6a4 4 0 0 1 8 0v2"/>'};
const STORE='malaysia-english-v1';
let curriculum={},allPhrases=[],shownPhrase=null;
let lessons=[],li=0,pi=0,mode='phrases',recall=false,revealed=false,learned=new Set(),storageOK=true;
let sequence=0,activeKind='',currentFinish=null,timer=null,waitFinish=null,toastTimer;
const audio=new Audio();audio.preload='none';audio.preservesPitch=true;
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad=n=>String(n).padStart(2,'0');
const lesson=()=>lessons[li];const phrase=()=>lesson().phrases[pi];
function message(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,2600);}
function save(){try{localStorage.setItem(STORE,JSON.stringify({lesson:lesson().id,phrase:pi,learned:[...learned]}));}catch{if(storageOK){storageOK=false;message('当前浏览器无法保存进度，仍可正常练习。');}}}
function restore(){try{const state=JSON.parse(localStorage.getItem(STORE)||'{}');const ids=new Set(lessons.flatMap(l=>l.phrases.map(p=>p.id)));learned=new Set((Array.isArray(state.learned)?state.learned:[]).filter(x=>ids.has(x)));li=Math.max(0,lessons.findIndex(l=>l.id===state.lesson));pi=Number.isInteger(state.phrase)?Math.max(0,Math.min(lesson().phrases.length-1,state.phrase)):0;}catch{li=0;pi=0;}}
function status(text,active=false){$('play-status').textContent=text;$('play-status').classList.toggle('active',active);}
function resetButtons(){$('show-play').textContent='▶ 播放这句话';$('show-status').textContent='';const ask=document.getElementById('ask-place');if(ask)ask.textContent='▶ 听问路句';for(const id of ['listen-button','slow-button','follow-button','dialogue-play'])$(id).classList.remove('is-active');$('listen-button').innerHTML='<span class="play-icon">▶</span> 听发音';$('slow-button').textContent='0.75× 慢速';$('follow-button').textContent='跟读练习';$('dialogue-play').textContent='▶ 播放整段对话';document.querySelectorAll('.dialogue-line.playing').forEach(x=>x.classList.remove('playing'));}
function stop(reset=true){sequence++;audio.pause();if(currentFinish)currentFinish(false);clearTimeout(timer);if(waitFinish){const done=waitFinish;waitFinish=null;done(false);}activeKind='';resetButtons();if(reset)status('听一遍，再跟着说一遍。');}
function delay(ms,token){return new Promise(resolve=>{if(token!==sequence)return resolve(false);waitFinish=resolve;timer=setTimeout(()=>{waitFinish=null;resolve(token===sequence);},ms);});}
function playFile(src,rate,token){return new Promise((resolve,reject)=>{if(token!==sequence)return resolve(false);let settled=false;const cleanup=()=>{audio.onended=null;audio.onerror=null;if(currentFinish===finish)currentFinish=null;};const finish=value=>{if(settled)return;settled=true;cleanup();resolve(value);};const fail=()=>{if(settled)return;settled=true;cleanup();reject(new Error('无法播放'));};currentFinish=finish;audio.onended=()=>finish(token===sequence);audio.onerror=fail;audio.src=src;audio.playbackRate=rate;audio.defaultPlaybackRate=rate;audio.preservesPitch=true;audio.play().catch(fail);});}
function playbackError(token){if(token!==sequence)return;stop(false);status('音频未能播放，请检查网络后重试。');message('请重试播放；微信内可改用 Safari 或 Chrome。');}
async function playPhrase(kind){if(activeKind===kind){stop();return;}stop(false);const token=sequence;activeKind=kind;const btn=$(kind+'-button');btn.classList.add('is-active');btn.textContent='■ 停止';status(kind==='follow'?'第 1 遍：先听，再跟着说。':'正在播放…',true);try{if(!await playFile(phrase().audio,kind==='slow'?.75:1,token))return;if(kind==='follow'){const pause=Math.max(4,Math.ceil(audio.duration)+1);for(let remaining=pause;remaining>0;remaining--){status('轮到你说 · '+remaining+' 秒',true);if(!await delay(1000,token))return;}status('第 2 遍：再听一次，核对读音。',true);if(!await playFile(phrase().audio,.85,token))return;}if(token===sequence){activeKind='';resetButtons();status(kind==='follow'?'现在再自己说一遍，熟练后点「这句我会了」。':'听完了，试着自己说一遍。');}}catch{playbackError(token);}}
async function playDialogue(index=null){const kind=index===null?'dialogue':'dialogue-'+index;if(activeKind===kind||index===null&&activeKind.startsWith('dialogue')){stop();return;}stop(false);const token=sequence;activeKind=kind;$('dialogue-play').textContent='■ 停止播放';$('dialogue-play').classList.add('is-active');try{const indices=index===null?lesson().dialogue.map((_,i)=>i):[index];for(const i of indices){document.querySelectorAll('.dialogue-line').forEach((x,n)=>x.classList.toggle('playing',i===n));if(!await playFile(lesson().dialogue[i].audio,1,token))return;if(i!==indices[indices.length-1]&&!await delay(700,token))return;}if(token===sequence){activeKind='';resetButtons();}}catch{playbackError(token);}}
function renderNav(){ $('lesson-select').innerHTML=lessons.map((l,i)=>`<option value="${i}" ${i===li?'selected':''}>${pad(i+1)} · ${escapeHtml(l.title)}（${l.phrases.length} 条）</option>`).join('');const total=lessons.reduce((sum,l)=>sum+l.phrases.length,0);$('total-progress').textContent=learned.size+' / '+total+' 条';$('progress-fill').style.width=learned.size/total*100+'%';$('lesson-nav').innerHTML=lessons.map((l,i)=>{const n=l.phrases.filter(p=>learned.has(p.id)).length;return `<button class="lesson-item ${i===li?'active':''}" data-lesson="${i}" ${i===li?'aria-current="step"':''}><span class="unit-number">${pad(i+1)}</span><span><span class="unit-title">${escapeHtml(l.title)}</span><span class="unit-desc">${l.phrases.length} 条${l.dialogue.length?' · 场景对话':' · 地名点读'}</span></span><span class="lesson-check">${n===l.phrases.length?'✓':n+'/'+l.phrases.length}</span></button>`;}).join('');}
function renderList(){const hidden=recall;$('phrase-list').innerHTML=lesson().phrases.map((p,i)=>`<button class="phrase-row ${i===pi?'selected':''}" data-phrase="${i}" ${i===pi?'aria-current="true"':''}><span class="row-number">${pad(i+1)}</span><span><span class="row-zh">${escapeHtml(p.zh)}</span>${hidden?'':`<span class="row-en" lang="en">${escapeHtml(p.en)}</span>`}</span><span class="row-check">${learned.has(p.id)?'✓':i===pi?'▶':''}</span></button>`).join('');}
function renderCard(){const p=phrase();$('phrase-total').textContent=lesson().phrases.length;$('phrase-list-title').textContent='这一课的 '+lesson().phrases.length+' 条';$('card-label').textContent=p.kind?((p.city||'')+' · '+p.kind):'你可以这样说';renderPlace(p);$('phrase-counter').innerHTML=pad(pi+1)+' <span>/ '+pad(lesson().phrases.length)+'</span>';$('phrase-zh').textContent=p.zh;$('phrase-en').textContent=p.en;$('phrase-chunks').textContent=p.chunks;$('phrase-tip').textContent=recall&&!revealed?'先用英文说出中文意思，再点「查看英文」核对。':(p.tip||'按斜线分小段读，再连起来说一遍。');$('english-block').hidden=recall&&!revealed;$('reveal-button').hidden=!recall||revealed;$('recall-toggle').textContent=recall?'显示英文一起读':'遮住英文，自己说';$('recall-toggle').setAttribute('aria-pressed',String(recall));$('mastered-badge').hidden=!learned.has(p.id);$('master-button').classList.toggle('learned',learned.has(p.id));$('master-button').textContent=learned.has(p.id)?'✓ 已掌握 · 点此撤销':'✓ 这句我会了';$('master-button').setAttribute('aria-pressed',String(learned.has(p.id)));$('previous-button').disabled=pi===0;$('next-button').disabled=pi===lesson().phrases.length-1;renderList();}
function renderDialogue(){$('dialogue-lines').innerHTML=lesson().dialogue.map((line,i)=>`<article class="dialogue-line ${line.role==='旅客'?'mine':''}"><header><span>${line.role==='旅客'?'你':escapeHtml(line.role)}</span><button data-dialogue="${i}" aria-label="播放第${i+1}句：${escapeHtml(line.en)}">▶</button></header><p lang="en" class="dialogue-en">${escapeHtml(line.en)}</p><p class="dialogue-zh">${escapeHtml(line.zh)}</p></article>`).join('');}
function renderMode(){if(!lesson().dialogue.length)mode='phrases';$('dialogue-tab').hidden=!lesson().dialogue.length;$('practice-panel').hidden=mode!=='phrases';$('dialogue-panel').hidden=mode!=='dialogue';for(const id of ['phrases','dialogue']){const selected=mode===id;$(id+'-tab').setAttribute('aria-selected',String(selected));$(id+'-tab').tabIndex=selected?0:-1;}}
function render(){const l=lesson();renderNav();$('lesson-kicker').textContent='UNIT '+pad(li+1)+' / '+pad(lessons.length);$('lesson-title').textContent=l.title;$('lesson-subtitle').textContent=l.subtitle;$('lesson-symbol').innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[l.icon]||icons.plane)+'</svg>';renderCard();renderDialogue();renderMode();}
function selectLesson(index){if(!Number.isInteger(index)||index<0||index>=lessons.length)throw new Error('场景不存在');stop();li=index;pi=0;revealed=false;save();render();document.querySelector('.lesson-item.active')?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});}
function selectPhrase(index){if(!Number.isInteger(index)||index<0||index>=lesson().phrases.length)throw new Error('短句不存在');stop();pi=index;revealed=false;save();renderCard();}
function markPhrase(){stop();const p=phrase();if(learned.has(p.id)){learned.delete(p.id);}else{learned.add(p.id);if(lesson().phrases.every(x=>learned.has(x.id)))message('这一课的 '+lesson().phrases.length+' 条都掌握了！');else message('记住了！继续练下一句。');}save();renderNav();renderCard();}
function events(){extraEvents();$('lesson-nav').addEventListener('click',e=>{const b=e.target.closest('[data-lesson]');if(b)selectLesson(Number(b.dataset.lesson));});$('phrase-list').addEventListener('click',e=>{const b=e.target.closest('[data-phrase]');if(b){selectPhrase(Number(b.dataset.phrase));$('phrase-card').scrollIntoView({behavior:'smooth',block:'center'});}});for(const id of ['phrases','dialogue'])$(id+'-tab').addEventListener('click',()=>{stop();mode=id;renderMode();});document.querySelector('.tabbar').addEventListener('keydown',e=>{if(lesson().dialogue.length&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const id=mode==='phrases'?'dialogue':'phrases';$(id+'-tab').click();$(id+'-tab').focus();}});$('previous-button').onclick=()=>selectPhrase(pi-1);$('next-button').onclick=()=>selectPhrase(pi+1);$('master-button').onclick=markPhrase;$('recall-toggle').onclick=()=>{stop();recall=!recall;revealed=false;renderCard();};$('reveal-button').onclick=()=>{revealed=true;renderCard();};for(const k of ['listen','slow','follow'])$(k+'-button').onclick=()=>playPhrase(k);$('dialogue-play').onclick=()=>playDialogue();$('dialogue-lines').onclick=e=>{const b=e.target.closest('[data-dialogue]');if(b)playDialogue(Number(b.dataset.dialogue));};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',()=>stop());}
function registerLearningTool(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'open_travel_english_phrase',title:'打开旅行英语短句',description:'按场景 ID 和短句序号打开对应练习卡，不播放音频，不改变掌握状态。',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:lessons.map(l=>l.id)},phraseNumber:{type:'integer',minimum:1,maximum:Math.max(...lessons.map(l=>l.phrases.length))}},required:['lessonId','phraseNumber'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['lessonId','phraseNumber'].includes(k)))throw new Error('无效输入');const index=lessons.findIndex(l=>l.id===input.lessonId);if(index<0||!Number.isInteger(input.phraseNumber)||input.phraseNumber<1||input.phraseNumber>(lessons[index]?.phrases.length||0))throw new Error('请选择有效的场景和该场景内的短句序号');mode='phrases';selectLesson(index);selectPhrase(input.phraseNumber-1);return {lesson:lesson().title,phrase:phrase().en,chinese:phrase().zh};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
async function init(){try{const response=await fetch('curriculum.json?v=2');if(!response.ok)throw new Error('load');const data=await response.json();curriculum=data;lessons=data.lessons;if(!Array.isArray(lessons)||!lessons.length)throw new Error('data');allPhrases=lessons.flatMap((l,lessonIndex)=>l.phrases.map((p,phraseIndex)=>({...p,lessonIndex,phraseIndex,lessonTitle:l.title})));restore();render();events();registerLearningTool();}catch{$('practice-panel').innerHTML='<div class="phrase-card"><h3>课程暂时没有加载出来</h3><p>请检查网络，刷新后再试。</p><button class="primary-button" onclick="location.reload()">重新加载</button></div>';}}
function safeUrl(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:null;}catch{return null;}}
function renderPlace(p){const box=$('place-details');box.hidden=!p.kind||recall&&!revealed;if(box.hidden)return;const source=safeUrl(p.source);const map=p.mapQuery?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.mapQuery):null;box.innerHTML=(p.askEn?'<p lang="en">'+escapeHtml(p.askEn)+'</p>':'')+'<div class="place-actions">'+(p.askAudio?'<button id="ask-place">▶ 听问路句</button>':'')+(map?'<a href="'+escapeHtml(map)+'" target="_blank" rel="noopener noreferrer">地图找这个地方 ↗</a>':'')+(source?'<a href="'+escapeHtml(source)+'" target="_blank" rel="noopener noreferrer">名称来源 ↗</a>':'')+'</div>';if(p.askAudio)$('ask-place').onclick=()=>playExtra(p.askAudio,'place');}
async function playExtra(src,kind){if(activeKind===kind){stop();return;}stop(false);const token=sequence;activeKind=kind;const button=kind==='show'?$('show-play'):$('ask-place');if(button)button.textContent='■ 停止播放';if(kind==='show')$('show-status').textContent='正在播放…';else status('正在播放问路句…',true);try{if(!await playFile(src,1,token))return;if(token===sequence){activeKind='';resetButtons();if(kind==='show')$('show-status').textContent='播放完成';else status('说不清时，也可以把英文名给对方看。');}}catch{playbackError(token);if(kind==='show')$('show-status').textContent='无法播放，请检查网络后重试。';}}
function showCard(p){stop();shownPhrase=p;if($('help-dialog').open)$('help-dialog').close();$('show-english').textContent=p.en;$('show-chinese').textContent=p.zh;$('show-tip').textContent=p.tip||'';$('show-dialog').showModal();}
function openHelp(){stop();const rows=allPhrases.filter(p=>p.urgent);$('help-phrases').innerHTML=rows.map(p=>'<button class="help-row" data-help-id="'+escapeHtml(p.id)+'"><b>'+escapeHtml(p.zh)+'</b><span lang="en">'+escapeHtml(p.en)+'</span></button>').join('');const emergency=curriculum.emergency;const source=safeUrl(emergency?.source);$('emergency-contact').innerHTML=emergency?.number==='999'?'<a class="emergency-link" href="tel:999"><span>马来西亚紧急求助</span><span>拨打 999 ↗</span></a><p class="emergency-source">紧急情况直接求助，不必先完成英语练习。'+(source?' <a target="_blank" rel="noopener noreferrer" href="'+escapeHtml(source)+'">官方号码来源</a>':'')+'</p>':'';$('help-dialog').showModal();}
const normalized=s=>String(s||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'');
function searchPhrases(){const query=$('phrase-search').value.trim();$('clear-search').hidden=!query;$('search-results').hidden=!query;$('search-status').hidden=!query;if(!query){$('search-results').innerHTML='';return;}const parts=normalized(query).split(/\s+/).filter(Boolean);const matches=allPhrases.filter(p=>{const text=normalized([p.zh,p.en,p.tip,p.city,p.kind,p.lessonTitle].join(' '));return parts.every(q=>text.includes(q));});$('search-status').textContent=matches.length?'找到 '+matches.length+' 条'+(matches.length>60?'，先显示前 60 条':''):'没有找到，试试「抽筋」「微信」「登机口」或英文地名。';$('search-results').innerHTML=matches.slice(0,60).map(p=>'<button class="search-result" data-result-id="'+escapeHtml(p.id)+'"><strong>'+escapeHtml(p.zh)+'</strong><span>'+escapeHtml(p.en)+'</span><span>'+escapeHtml(p.lessonTitle)+'</span></button>').join('');}
function extraEvents(){$('lesson-select').onchange=e=>selectLesson(Number(e.target.value));$('phrase-search').addEventListener('input',searchPhrases);$('clear-search').onclick=()=>{$('phrase-search').value='';searchPhrases();$('phrase-search').focus();};$('search-results').onclick=e=>{const b=e.target.closest('[data-result-id]');if(!b)return;const p=allPhrases.find(x=>x.id===b.dataset.resultId);if(!p)return;mode='phrases';selectLesson(p.lessonIndex);selectPhrase(p.phraseIndex);$('phrase-search').value='';searchPhrases();$('phrase-card').scrollIntoView({block:'center',behavior:'smooth'});};$('help-button').onclick=openHelp;$('help-close').onclick=()=>$('help-dialog').close();$('help-phrases').onclick=e=>{const b=e.target.closest('[data-help-id]');if(b){const p=allPhrases.find(x=>x.id===b.dataset.helpId);if(p)showCard(p);}};$('show-card-button').onclick=()=>showCard(phrase());$('show-close').onclick=()=>$('show-dialog').close();$('show-dialog').addEventListener('close',()=>stop());$('show-play').onclick=()=>{if(shownPhrase)playExtra(shownPhrase.audio,'show');};}
// Keep a single set of search and lesson controls, moving them into a phone sheet.
function setupMobileNavigation(){
  const media=window.matchMedia('(max-width: 700px)');
  const sheet=$('mobile-tools-dialog');
  const moves=[['.search-box','mobile-search-panel'],['.course-heading','mobile-lessons-panel'],['#lesson-nav','mobile-lessons-panel'],['.overall-progress','mobile-lessons-panel']].map(([selector,target])=>{
    const node=document.querySelector(selector),anchor=document.createComment('desktop control position');
    node.before(anchor);return {node,anchor,target:$(target)};
  });
  function setActive(id){document.querySelectorAll('.mobile-navigation button').forEach(button=>{if(button.id===id)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});}
  function sync(){
    if(sheet.open)sheet.close();
    for(const {node,anchor,target} of moves){if(media.matches)target.append(node);else anchor.after(node);}
  }
  function openPanel(kind){
    stop();$('mobile-tools-title').textContent=kind==='search'?'搜一句马上用':'选择练习场景';
    $('mobile-search-panel').hidden=kind!=='search';$('mobile-lessons-panel').hidden=kind!=='lessons';
    sheet.showModal();setActive('mobile-'+kind);
    if(kind==='search')$('phrase-search').focus({preventScroll:true});
    else document.querySelector('.lesson-item.active')?.scrollIntoView({block:'nearest'});
  }
  function returnToPractice(){
    if(sheet.open)sheet.close();
    requestAnimationFrame(()=>document.querySelector('.lesson-heading').scrollIntoView({block:'start',behavior:'smooth'}));
  }
  $('mobile-practice').onclick=returnToPractice;
  $('mobile-lessons').onclick=()=>openPanel('lessons');
  $('mobile-search').onclick=()=>openPanel('search');
  $('mobile-help').onclick=openHelp;
  $('mobile-tools-close').onclick=()=>sheet.close();
  sheet.addEventListener('close',()=>setActive('mobile-practice'));
  $('lesson-nav').addEventListener('click',event=>{if(media.matches&&event.target.closest('[data-lesson]'))returnToPractice();});
  $('search-results').addEventListener('click',event=>{if(media.matches&&event.target.closest('[data-result-id]')){$('phrase-search').blur();returnToPractice();}});
  for(const dialog of document.querySelectorAll('dialog')){
    dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();});
  }
  media.addEventListener('change',sync);sync();
}
setupMobileNavigation();
init();
